#!/usr/bin/env python3
"""Generate the 0.8.0 T01 valid-file fixtures.

Every file is built from repository-owned primitives, copied from an existing
repository fixture, or (for the optional real-world samples) copied from the
local F3D checkout whose provenance is recorded in README.md. No third-party
model data is copied without a recorded license.

Run from the repository root:

    python tests/fixtures/valid-file/generate_fixtures.py

The generated bytes are committed because ADR-0029 requires byte-exact
fixtures. Regenerating the generated files is deterministic; the copied
fixtures are byte-identical to their source.
"""

from __future__ import annotations

import argparse
import pathlib
import shutil
import struct
import zipfile

HERE = pathlib.Path(__file__).resolve().parent
ROOT = HERE.parents[2]


def write(name: str, data: str | bytes) -> None:
    path = HERE / name
    path.write_bytes(data.encode("utf-8") if isinstance(data, str) else data)
    print(f"wrote {path.relative_to(ROOT)} ({path.stat().st_size} bytes)")


def copy_from(name: str, source: pathlib.Path) -> None:
    if not source.is_file():
        print(f"skip {name}: missing source {source}")
        return
    shutil.copyfile(source, HERE / name)
    print(f"copied {name} ({ (HERE / name).stat().st_size } bytes) from {source}")


